-- ══════════════════════════════════════════════════════════════════════════
--  IMPORTACION DE PACIENTES — Excel del 03-09-2026
--
--  SOLO AGREGA los que faltan. ON CONFLICT (dni) DO NOTHING: si el DNI ya
--  existe, la fila se ignora por completo — no se pisa ningun dato del
--  paciente que ya estaba, asi que sus citas, pagos y paquetes quedan intactos.
--
--  Es idempotente: correrlo dos veces no duplica nada.
--
--  IRREVERSIBLE en el sentido de que agrega 7248 filas. Backup antes:
--    docker compose exec -T db pg_dump -U postgres -d BDClinicaSAAS -F c > ~/backups/antes-import.dump
-- ══════════════════════════════════════════════════════════════════════════

BEGIN;

SELECT 'ANTES' AS momento, count(*) AS pacientes FROM pacientes;

-- Tabla temporal: se cargan todas las filas del Excel y luego se insertan de una,
-- lo que permite reportar cuantas entraron y cuantas ya existian.
CREATE TEMP TABLE _import_pacientes (
    nombre           VARCHAR(100),
    apellido         VARCHAR(100),
    dni              VARCHAR(20),
    telefono         VARCHAR(20),
    correo           VARCHAR(150),
    fecha_nacimiento DATE,
    notas            TEXT
) ON COMMIT DROP;
















-- El Excel puede traer el mismo DNI dos veces con datos distintos: se queda el primero.
                       activo, sede_id, created_at, updated_at, saldo_a_favor)
SELECT DISTINCT ON (i.dni)
       i.nombre, i.apellido, i.dni, i.telefono, i.correo, i.fecha_nacimiento, i.notas,
       true,
       (SELECT id FROM sedes ORDER BY id LIMIT 1),
       now(), now(), 0
FROM _import_pacientes i
ORDER BY i.dni
ON CONFLICT (dni) DO NOTHING;

SELECT 'DESPUES' AS momento, count(*) AS pacientes FROM pacientes;
SELECT 'importados en esta corrida' AS detalle,
       count(*) FILTER (WHERE p.notas LIKE 'Importado del Excel del 03-09-2026%') AS filas
FROM pacientes p;

COMMIT;
